/**
 * Share cards (FR-24, §15.1, §11). The **render payload** is the whole truth of what an image
 * shows: the renderer draws exactly these fields and nothing else, so a test on the payload is
 * a test on the picture. Defaults exclude private notes, the exact question and the names of
 * people and places; each is opted in separately by the user, who sees the same render as a
 * preview. Nothing generated by a model appears on a card (no claims about real people, §11)
 * and there is no user identity to show — the app stores none.
 */

export interface ShareOptions {
  /** Show the reading's question (reading card only). */
  question: boolean;
  /** Show an excerpt of the user's own note (reading card only). */
  notes: boolean;
  /** Name the people and places the entries mention. */
  entities: boolean;
  /** Month card: name the journeys that moved (titles can carry names). */
  journeys: boolean;
}

export const DEFAULT_SHARE_OPTIONS: ShareOptions = {
  question: false,
  notes: false,
  entities: false,
  journeys: false,
};

export const NOTE_EXCERPT_MAX = 160;
export const QUESTION_MAX = 120;

export interface ShareCardBase {
  /** The one line under the wordmark: "A reading", "August 2026". */
  eyebrow: string;
  deckSystem: 'rws' | 'thoth' | 'mixed';
}

export interface ReadingCardPayload extends ShareCardBase {
  kind: 'reading';
  dateLabel: string;
  deckName: string;
  spreadName: string;
  cards: {
    position: string;
    name: string;
    reversed: boolean;
    /** Public art path (RWS) or null for the typographic treatment (Thoth). */
    artPath: string | null;
    /** Deck-native short glyph line: numeral / suit (typographic treatment). */
    caption: string | null;
  }[];
  themes: string[];
  question: string | null;
  note: string | null;
  entities: string[] | null;
}

export interface MonthCardPayload extends ShareCardBase {
  kind: 'month';
  monthLabel: string;
  readings: number;
  events: number;
  outcomes: number;
  recurring: { name: string; count: number; deckSystem: 'rws' | 'thoth' }[];
  themes: string[];
  journeys: string[] | null;
  entities: string[] | null;
}

export type ShareCardPayload = ReadingCardPayload | MonthCardPayload;

export interface ReadingForShare {
  occurredAt: string;
  deck: { name: string; system: 'rws' | 'thoth' };
  spread: { name: string };
  cards: {
    positionLabel: string;
    name: string;
    reversed: boolean;
    artPath: string | null;
    caption: string | null;
  }[];
  question: string | null;
  notes: string | null;
  themes: string[];
  entityLabels: string[];
}

const dateLabel = (iso: string) =>
  new Date(iso).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });

/** First sentence-ish chunk of a note, capped, with an ellipsis when cut. */
export function excerpt(text: string, max = NOTE_EXCERPT_MAX): string {
  const clean = text.replace(/\s+/g, ' ').trim();
  if (clean.length <= max) return clean;
  const cut = clean.slice(0, max);
  const at = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf(' '));
  return `${cut.slice(0, at > max / 2 ? at : max).trimEnd()}…`;
}

export function buildReadingCard(
  reading: ReadingForShare,
  options: Partial<ShareOptions> = {},
): ReadingCardPayload {
  const o = { ...DEFAULT_SHARE_OPTIONS, ...options };
  return {
    kind: 'reading',
    eyebrow: 'A reading',
    deckSystem: reading.deck.system,
    dateLabel: dateLabel(reading.occurredAt),
    deckName: reading.deck.name,
    spreadName: reading.spread.name,
    cards: reading.cards.slice(0, 10).map((c) => ({
      position: c.positionLabel,
      name: c.name,
      reversed: c.reversed,
      artPath: c.artPath,
      caption: c.caption,
    })),
    themes: reading.themes.slice(0, 4),
    question: o.question && reading.question ? excerpt(reading.question, QUESTION_MAX) : null,
    note: o.notes && reading.notes ? excerpt(reading.notes) : null,
    entities: o.entities && reading.entityLabels.length ? reading.entityLabels.slice(0, 6) : null,
  };
}

export interface MonthForShare {
  monthLabel: string;
  readings: number;
  events: number;
  outcomes: number;
  recurring: { name: string; count: number; deckSystem: 'rws' | 'thoth' }[];
  themes: string[];
  journeyTitles: string[];
  entityLabels: string[];
}

export function buildMonthCard(
  month: MonthForShare,
  options: Partial<ShareOptions> = {},
): MonthCardPayload {
  const o = { ...DEFAULT_SHARE_OPTIONS, ...options };
  const systems = new Set(month.recurring.map((r) => r.deckSystem));
  return {
    kind: 'month',
    eyebrow: 'My month in tarot',
    deckSystem: systems.size === 1 ? [...systems][0]! : 'mixed',
    monthLabel: month.monthLabel,
    readings: month.readings,
    events: month.events,
    outcomes: month.outcomes,
    recurring: month.recurring.slice(0, 3),
    themes: month.themes.slice(0, 4),
    journeys: o.journeys && month.journeyTitles.length ? month.journeyTitles.slice(0, 3) : null,
    entities: o.entities && month.entityLabels.length ? month.entityLabels.slice(0, 6) : null,
  };
}

/** Parses `?question=1&notes=1…` into options; anything else is the private default. */
export function parseShareOptions(params: Record<string, string | undefined>): ShareOptions {
  const on = (v: string | undefined) => v === '1' || v === 'true';
  return {
    question: on(params.question),
    notes: on(params.notes),
    entities: on(params.entities),
    journeys: on(params.journeys),
  };
}

export function shareOptionsQuery(o: ShareOptions): string {
  const q = new URLSearchParams();
  for (const k of ['question', 'notes', 'entities', 'journeys'] as const) if (o[k]) q.set(k, '1');
  const s = q.toString();
  return s ? `?${s}` : '';
}
